// src/hooks/useSearchUsers.js - VERSÃO DEFINITIVA
import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, getDocs } from "firebase/firestore";

export default function useSearchUsers() {
    const [allUsers, setAllUsers] = useState([]);
    const [search, setSearch] = useState("");

    useEffect(() => {
        const loadUsers = async () => {
            try {
                const snap = await getDocs(collection(db, "users"));
                const usersData = snap.docs.map(d => {
                    const data = d.data();
                    // ✅ GARANTIR que todos os campos obrigatórios existam
                    return {
                        id: d.id,
                        nome: data.nome || data.displayName || data.email?.split('@')[0] || "Usuário",
                        email: data.email || "",
                        avatarUrl: data.avatarUrl || data.photoURL || "",
                        online: data.online || false,
                        ...data // Mantém outros campos se existirem
                    };
                });

                console.log("✅ Usuários carregados:", usersData);
                setAllUsers(usersData);
            } catch (error) {
                console.error("Erro ao carregar usuários:", error);
                setAllUsers([]);
            }
        };
        loadUsers();
    }, []);

    const searchUsers = (text) => {
        setSearch(text.toLowerCase());
    };

    // ✅ CORREÇÃO DEFINITIVA: Verificações redundantes
    const filtered = allUsers.filter(u => {
        if (!u) return false;

        const email = (u.email || "").toLowerCase();
        const nome = (u.nome || "").toLowerCase();
        const searchTerm = search || "";

        return email.includes(searchTerm) || nome.includes(searchTerm);
    });

    return {
        allUsers,
        filtered,
        searchUsers,
        search
    };
}
